using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "EnemyActionLogic_AllCompanions", menuName = "Data/Battle/Logics/Enemy Action/All Companions")]
public class EnemyActionLogic_AllCompanions : EnemyActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	public override void ActivateAction(BattleAction battleAction, int actionAmount, GameObject source)
	{
		base.ActivateAction(battleAction, actionAmount, source);
		List<GameObject> activeCompanions = currentCompanions.ActiveCompanions;
		if (actionAmount == EffectsValues.NO_VALUE)
		{
			battleAction.AreaCastTarget(activeCompanions, source);
		}
		else
		{
			battleAction.AreaCastTargetAmount(activeCompanions, actionAmount, source);
		}
	}
}
